command:
if (!game.user.isGM) return ui.notifications.warn('Repair Items (Scene) is GM-only.');

const scene = canvas.scene;
if (!scene) return ui.notifications.warn('No map is active.');

const result = await game.emblemRpg.api.development.repairItems({ scope: 'scene', sceneUuid: scene.uuid });

console.group(`emblem-rpg | Repair Items (Scene) — ${result.ok ? 'settled' : 'refused'}`);
console.log(result.ok ? result.data : result);
console.groupEnd();
